async function main() {
  console.log("Starting quiz seeding for Class 11 Physics Part 2...\n");

  for (const chapter of chapters) {
    console.log(`Processing: ${chapter.name} (${chapter.id})`);

    // Delete existing questions
    const deleted = await prisma.question.deleteMany({
      where: { chapterId: chapter.id },
    });
    console.log(`  Deleted ${deleted.count} existing questions.`);

    // Insert new questions
    const data = chapter.questions.map((q) => ({
      chapterId: chapter.id,
      questionText: q.questionText,
      optionA: q.optionA,
      optionB: q.optionB,
      optionC: q.optionC,
      optionD: q.optionD,
      correctOption: q.correctOption,
      solution: q.solution,
    }));

    const created = await prisma.question.createMany({ data });
    console.log(`  Inserted ${created.count} questions.\n`);
  }

  console.log("Done! All 7 chapters seeded with 25 questions each (175 total).");
}

main()
  .catch((e) => {
    console.error("Error:", e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
